private void setDataEditable(boolean allowEdit)
{
    FormDataSource TAMRebateTable_ds = this.formRun().dataSource(tablestr(TAMRebateTable));
    TAMRebateTable_ds.allowEdit(allowEdit);
    TAMRebateTable_ds.allowCreate(allowEdit);
    TAMRebateTable_ds.allowDelete(allowEdit);

    FormDataSource TAMRebateDate_ds = this.formRun().dataSource(tablestr(TAMRebateDate));
    TAMRebateDate_ds.allowEdit(allowEdit);
    TAMRebateDate_ds.allowDelete(allowEdit);

    FormDataSource TAMRebateLine_ds = this.formRun().dataSource(tablestr(TAMRebateLine));
    TAMRebateLine_ds.allowEdit(allowEdit);
    TAMRebateLine_ds.allowCreate(allowEdit);
    TAMRebateLine_ds.allowDelete(allowEdit);

    FormDataSource inventDim_ds = this.formRun().dataSource(tablestr(InventDim));
    inventDim_ds.allowEdit(allowEdit);
    inventDim_ds.allowCreate(allowEdit);

    this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateTablePriceAttributeGroupEdit)).enabled(allowEdit);
}

private boolean alreadyHasTransaction(TAMRebateTable rebateTable)
{
    TAMRebateTrans rebateTrans;
    select firstonly RecId from rebateTrans
            where rebateTrans.RebateId == rebateTable.RebateId;

    return rebateTrans.RecId != 0;
}

public int active()
{
    int ret = next active();

    if (TAMRebateDealGUPExtensionHelper::shouldShowGUPUI(this.formRun()))
    {
        FormDataSource TAMRebateTable_ds = this.formRun().dataSource(tablestr(TAMRebateTable));
        TAMRebateTable rebateTable = TAMRebateTable_ds.cursor();
        FormDataSource TAMRebateDeal_ds = this.formRun().dataSource(tablestr(TAMRebateDeal));
        TAMRebateDeal  rebateDeal = TAMRebateDeal_ds.cursor();

        FormDataSource TAMRebateDate_ds = this.formRun().dataSource(tablestr(TAMRebateDate));
        TAMRebateDate_ds.allowCreate(rebateDeal.RebateActive == NoYes::No);

        if (!this.alreadyHasTransaction(rebateTable) && rebateDeal.RebateActive == NoYes::No)
        {
            this.setDataEditable(true);
        }
        else
        {
            this.setDataEditable(false);
        }
    }

    return ret;
}
